INSERT OR IGNORE INTO news (
  slug, title, category, published_date, source_name, source_url,
  summary, body, image_url, image_credit, image_source, verification_json, source
) VALUES (
  'gauteng-begins-repairs-seven-bridges-tshwane-2026-10-14',
  'Gauteng begins repairs on seven bridges around Tshwane',
  'Traffic', '2026-10-14', 'Pretoria Rekord', 'https://www.citizen.co.za/rekord/news-headlines/2026/10/14/gauteng-department-launches-multi-million-rand-tshwane-bridge-project/',
  'The Gauteng government has started a province-wide project to repair seven ageing bridges on routes around Atteridgeville, Valhalla and northwest Tshwane.',
  'A sod-turning ceremony this week marked the official start of work to rehabilitate seven bridges on provincial routes around Tshwane. Gauteng''s roads MEC, Kedibone Diale-Tlabela, attended alongside Tshwane''s MMC for roads, Tlangi Mogale. The seven structures are two spans where the R101 crosses the Hennops River just south of Valhalla, three bridges on the R511 to the southwest of Atteridgeville, one on a nearby gravel road, and a seventh on Van der Hoff Road, which is also numbered the R514, through the city''s northwest.

Under the department''s Bridge Management System, crews will repair rails and parapets, fit new expansion joints, seal cracks, repaint steel, widen some of the bridges and resurface decks and approaches. A newly appointed contractor has a 12-month contract, and officials aim to finish all seven structures by August 2027. Diale-Tlabela said the province''s roads are needed to keep people, goods and services moving, and that a bridge left to deteriorate puts both safety and the local economy at risk. She asked motorists to watch for temporary traffic controls near each site.',
  NULL, NULL, NULL,
  '["https://www.citizen.co.za/rekord/news-headlines/2026/10/14/gauteng-department-launches-multi-million-rand-tshwane-bridge-project/", "https://www.sanews.gov.za/node/84951", "https://www.gov.za/news/media-statements/gauteng-roads-and-transport-rehabilitates-seven-tshwane-bridges-13-oct-2026"]',
  'agent'
);
INSERT OR IGNORE INTO news (
  slug, title, category, published_date, source_name, source_url,
  summary, body, image_url, image_credit, image_source, verification_json, source
) VALUES (
  'chantelle-orchards-sewage-wetland-tshwane-2026-10-16',
  'Sewage flowing into Orchards wetland near creche and homes',
  'Utilities', '2026-10-16', 'Pretoria Rekord', 'https://www.citizen.co.za/rekord/news-headlines/2026/10/16/tshwane-wetland-sewage-spill-sparks-health-concerns-in-the-orchards/',
  'Chantelle residents in The Orchards say raw sewage has polluted a nearby wetland for weeks, and the city says a blocked stormwater drain is to blame.',
  'Residents of Chantelle in The Orchards say raw sewage has been flowing into a nearby wetland for weeks, close to a creche and homes. The Democratic Alliance''s Gauteng environment spokesperson, Leanne de Jager, said residents have reported a strong smell and more snakes and rodents around the polluted area, and called on the City of Tshwane to repair the leaking sewer urgently. Ward 4 community leader Raymond Ditsi said residents have logged the problem repeatedly, under different service request numbers, without a lasting fix.

City spokesperson Lindela Mashigo responded that an investigation by the metro''s regional technical team traced the pollution to an older sewer blockage, made worse by a blocked stormwater drain that let stagnant water build up in the wetland. Officials have passed the matter to the city''s Roads and Stormwater Section for priority attention, and say clearing the stormwater channel should remove the smell. The DA wants water-quality testing done and a repair timeline published, warning that untreated sewage can carry disease-causing organisms that pose a particular risk to young children.',
  NULL, NULL, NULL,
  '["https://www.citizen.co.za/rekord/news-headlines/2026/10/16/tshwane-wetland-sewage-spill-sparks-health-concerns-in-the-orchards/", "https://dagpl.substack.com/p/the-orchards-sewage-spills-put-tshwane"]',
  'agent'
);
